mapper.select:
SELECT ROW_NUMBER() OVER(ORDER BY apr16_appl_type, apr16_stamp_repr_corp_nm COLLATE "ko_KR.utf8") AS stamp_doc_id , f_cdnm('CorpDocStampApplType', apr16_appl_type, #{companyId}, f_today()) AS appl_type_name , apr16_stamp_repr_corp_nm AS stamp_repr_corp_name , COALESCE(SUM(apr16_doc_issue_qty),0) AS doc_issue_qty , COALESCE(SUM(apr16_doc_use_qty) ,0) AS doc_use_qty , SUM(apr16_doc_remain_qty) AS doc_remain_qty FROM ( SELECT apr16_stamp_doc.* , CASE WHEN apr16_appl_type = '2' THEN COALESCE(apr15_corp_nm, sys01_company_nm) ELSE apr10_stamp_nm END AS apr16_stamp_repr_corp_nm , COALESCE(apr16_doc_issue_qty,0) - COALESCE(apr16_doc_use_qty,0) AS apr16_doc_remain_qty FROM apr16_stamp_doc LEFT JOIN apr10_stamp ON apr10_stamp_id = apr16_stamp_id LEFT JOIN apr15_repr_corp ON apr15_repr_corp_id = apr16_repr_corp_id LEFT JOIN sys01_company ON sys01_company_id = apr16_repr_corp_id WHERE apr16_company_id = #{companyId}
AND apr16_appl_type = #{applType}
AND apr16_appl_type IN ('1', '2')
AND (( #{applType} = '1' AND apr16_stamp_id = #{stampReprCorpId}) OR (#{applType} = '2' AND apr16_repr_corp_id = #{stampReprCorpId}))
AND apr16_reg_date IS NOT NULL ) t GROUP BY apr16_appl_type, apr16_stamp_repr_corp_nm

SELECT ROW_NUMBER() OVER(ORDER BY apr16_appl_type, apr16_stamp_repr_corp_nm COLLATE "ko_KR.utf8") AS stamp_doc_id , f_cdnm('CorpDocStampApplType', apr16_appl_type, #{companyId}, f_today()) AS appl_type_name , apr16_appl_type AS appl_type , apr16_stamp_repr_corp_nm AS stamp_repr_corp_name , apr16_stamp_id AS stamp_id , apr16_repr_corp_id AS repr_corp_id FROM ( SELECT apr16_stamp_doc.* , CASE WHEN apr16_appl_type = '2' THEN COALESCE(apr15_corp_nm, sys01_company_nm) ELSE apr10_stamp_nm END AS apr16_stamp_repr_corp_nm , COALESCE(apr16_doc_issue_qty,0) - COALESCE(apr16_doc_use_qty,0) AS apr16_doc_remain_qty FROM apr16_stamp_doc LEFT JOIN apr10_stamp ON apr10_stamp_id = apr16_stamp_id LEFT JOIN apr15_repr_corp ON apr15_repr_corp_id = apr16_repr_corp_id LEFT JOIN sys01_company ON sys01_company_id = apr16_repr_corp_id WHERE apr16_company_id = #{companyId}
AND apr16_appl_type = #{applType}
AND apr16_appl_type IN ('1', '2')
AND apr16_reg_date IS NOT NULL ) t GROUP BY apr16_appl_type, apr16_stamp_repr_corp_nm, apr16_stamp_id, apr16_repr_corp_id

SELECT apr16_appl_date
  FROM apr16_stamp_doc
 WHERE apr16_stamp_doc_id = #{stampDocId}
   AND apr16_company_id   = #{companyId}

SELECT COUNT(*)
  FROM apr16_stamp_doc
 WHERE apr16_stamp_doc_id = #{stampDocId}
   AND apr16_company_id   = #{companyId}

