UPDATE apr16_stamp_doc
   SET apr16_reg_date      = #{r.regDate}
     , apr16_appl_type     = #{r.applType}
     , apr16_stamp_id      = #{r.stampId}
     , apr16_repr_corp_id  = #{r.reprCorpId}
     , apr16_doc_issue_qty = #{r.docIssueQty}
     , apr16_doc_use_qty   = #{r.docUseQty}
     , apr16_provide_co    = #{r.provideCo}
     , apr16_purpose       = #{r.purpose}
     , apr16_note          = #{r.note}
     , apr16_appr_id       = #{r.apprId}
 WHERE apr16_stamp_doc_id = #{r.stampDocId}
   AND apr16_company_id   = #{companyId}

